/// <summary>
/// <see href="https://dom.spec.whatwg.org/#abortsignal">DOM Standard: 3.2 Interface AbortSignal</see>
/// </summary>
[ECMAScript]
[Description("@#AbortSignal")]
public class AbortSignal : EventTarget
{
    /// <summary>
    /// Though promises do not have a built-in aborting mechanism, many APIs using them require abort semantics. AbortController is meant to support these requirements by providing an abort() method that toggles the state of a corresponding AbortSignal object. The API which wishes to support aborting can accept an AbortSignal object, and use its state to determine how to proceed.
    /// </summary>
    /// <remarks>
    /// <see href="https://dom.spec.whatwg.org/#dom-abortsignal-abort">DOM Standard: 3.2 Interface AbortSignal</see>
    /// </remarks>
    /// <example>
    /// <code>AbortSignal.abort(reason)</code>
    /// </example>
    /// <param name="reason">APIs that rely upon AbortController are encouraged to respond to abort() by rejecting any unsettled promise with the AbortSignal&apos;s AbortSignal/abort reason. <see href="https://dom.spec.whatwg.org/#dom-abortsignal-abort-reason-reason">DOM Standard: 3.2 Interface AbortSignal</see></param>
    [Description("@#abort")]
    public static extern AbortSignal Abort(object? reason = default);

    /// <summary>
    /// <see href="https://dom.spec.whatwg.org/#dom-abortsignal-timeout">DOM Standard: 3.2 Interface AbortSignal</see>
    /// </summary>
    /// <example>
    /// <code>AbortSignal.timeout(milliseconds)</code>
    /// </example>
    /// <param name="milliseconds"><see href="https://dom.spec.whatwg.org/#dom-abortsignal-timeout-milliseconds-milliseconds">DOM Standard: 3.2 Interface AbortSignal</see></param>
    [Description("@#timeout")]
    public static extern AbortSignal Timeout(ulong milliseconds);

    /// <summary>
    /// <see href="https://dom.spec.whatwg.org/#dom-abortsignal-any">DOM Standard: 3.2 Interface AbortSignal</see>
    /// </summary>
    /// <example>
    /// <code>AbortSignal.any(signals)</code>
    /// </example>
    /// <param name="signals"><see href="https://dom.spec.whatwg.org/#dom-abortsignal-any-signals-signals">DOM Standard: 3.2 Interface AbortSignal</see></param>
    [Description("@#any")]
    public static extern AbortSignal Any(AbortSignal[] signals);

    /// <summary>
    /// If an AbortSignal is passed for options&apos;s signal, then the event listener will be removed when signal is aborted.
    /// </summary>
    /// <remarks>
    /// <see href="https://dom.spec.whatwg.org/#dom-abortsignal-aborted">DOM Standard: 3.2 Interface AbortSignal</see>
    /// </remarks>
    /// <example>
    /// <code>signal.aborted</code>
    /// </example>
    [Description("@#aborted")]
    public extern bool Aborted { get; }

    /// <summary>
    /// APIs that rely upon AbortController are encouraged to respond to abort() by rejecting any unsettled promise with the AbortSignal&apos;s AbortSignal/abort reason.
    /// </summary>
    /// <remarks>
    /// <see href="https://dom.spec.whatwg.org/#dom-abortsignal-reason">DOM Standard: 3.2 Interface AbortSignal</see>
    /// </remarks>
    /// <example>
    /// <code>signal.reason</code>
    /// </example>
    [Description("@#reason")]
    public extern object Reason { get; }

    /// <summary>
    /// <see href="https://dom.spec.whatwg.org/#dom-abortsignal-throwifaborted">DOM Standard: 3.2 Interface AbortSignal</see>
    /// </summary>
    /// <example>
    /// <code>signal.throwIfAborted()</code>
    /// </example>
    [Description("@#throwIfAborted")]
    public extern void ThrowIfAborted();

    /// <summary>
    /// The onabort attribute is an event handler IDL attribute for the onabort event handler, whose event handler event type is abort.
    /// </summary>
    /// <remarks>
    /// <see href="https://dom.spec.whatwg.org/#dom-abortsignal-onabort">DOM Standard: 3.2 Interface AbortSignal</see>
    /// </remarks>
    [Description("@#onabort")]
    public extern EventHandler Onabort { get; set; }
}

