    [Description("@#enqueue")]
    public extern void Enqueue(object? chunk = default);

    /// <summary>
    /// <see href="https://streams.spec.whatwg.org/#ts-default-controller-error">Streams Standard: 6.3.3 Methods and properties</see>
    /// </summary>
    /// <example>
    /// <code>controller.error(e)</code>
    /// </example>
    /// <param name="reason"><see href="https://streams.spec.whatwg.org/#dom-transformstreamdefaultcontroller-error-reason-reason">Streams Standard: 6.3.1 Interface definition</see></param>
    [Description("@#error")]
    public extern void Error(object? reason = default);

    /// <summary>
    /// (Note that there is no need to call controller.terminate() inside flush(); the stream is already in the process of successfully closing down, and terminating it would be counterproductive.)
    /// </summary>
    /// <remarks>
    /// <see href="https://streams.spec.whatwg.org/#ts-default-controller-terminate">Streams Standard: 6.3.3 Methods and properties</see>
    /// </remarks>
    /// <example>
    /// <code>controller.terminate()</code>
    /// </example>
    [Description("@#terminate")]
    public extern void Terminate();
}

