    /// </summary>
    [Description("@#positionAlign")]
    public extern PositionAlignSetting PositionAlign { get; set; }

    /// <summary>
    /// <see href="https://w3c.github.io/webvtt/#dom-vttcue-size">WebVTT: The Web Video Text Tracks Format: 9.1 The VTTCue interface</see>
    /// </summary>
