    public extern AttributionAggregationServices AggregationServices { get; }

    /// <summary>
    /// A set of sites, both impression sites and intermediary sites, that might have called the saveImpression() API. If not empty, only impressions recorded by one of the listed sites are eligible to match this conversion.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/attribution/#dom-attribution-saveimpression">Attribution Level 1: 4.3 Save Impression Algorithm</see>
    /// </remarks>
    /// <param name="options"><see href="https://w3c.github.io/attribution/#dom-attribution-saveimpression-options-options">Attribution Level 1: 3.4 Saving Impressions</see></param>
    [Description("@#saveImpression")]
    public extern PromiseResult<AttributionImpressionResult> SaveImpression(AttributionImpressionOptions options);

    /// <summary>
    /// The top-level conversion sites where conversions for this impression can occur, identified by their domain names. The measureConversion() method will only attribute to this impression when called by one of the indicated sites. If empty, any conversion site will match.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/attribution/#dom-attribution-measureconversion">Attribution Level 1: 4.4 Measure Conversion Algorithm</see>
    /// </remarks>
    /// <param name="options"><see href="https://w3c.github.io/attribution/#dom-attribution-measureconversion-options-options">Attribution Level 1: 3.5 Requesting Attribution for a Conversion</see></param>
    [Description("@#measureConversion")]
    public extern PromiseResult<AttributionConversionResult> MeasureConversion(AttributionConversionOptions options);
}

