/// <remarks>
/// <see href="https://w3c.github.io/selection-api/#dom-selection">Selection API: 3 Selection interface</see>
/// </remarks>
[ECMAScript]
[Description("@#Selection")]
public class Selection
{
    /// <summary>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-anchornode">Selection API: 3 Selection interface</see>
    /// </summary>
    [Description("@#anchorNode")]
