    /// </summary>
    [Description("@#focusOffset")]
    public extern uint FocusOffset { get; }

    /// <summary>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-iscollapsed">Selection API: 3 Selection interface</see>
    /// </summary>
    [Description("@#isCollapsed")]
    public extern bool IsCollapsed { get; }

    /// <summary>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-rangecount">Selection API: 3 Selection interface</see>
    /// </summary>
    [Description("@#rangeCount")]
    public extern uint RangeCount { get; }

    /// <summary>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-type">Selection API: 3 Selection interface</see>
    /// </summary>
    [Description("@#type")]
    public extern string Type { get; }

    /// <summary>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-direction">Selection API: 3 Selection interface</see>
    /// </summary>
    [Description("@#direction")]
    public extern string Direction { get; }

    /// <summary>
    /// Thus subsequent calls of this method returns the same range object if nothing has removed this&apos;s range in the meantime. In particular, getSelection().getRangeAt(0) === getSelection().getRangeAt(0) evaluates to true if the selection is not empty.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-getrangeat">Selection API: 3 Selection interface</see>
    /// </remarks>
    [Description("@#getRangeAt")]
    public extern Range GetRangeAt(uint index);

    /// <summary>
    /// For instance, if the DOM changes in a way that changes the range&apos;s boundary points, or a script modifies the boundary points of the range, the same range object must continue to be associated with the selection. However, if the user changes the selection or a script calls addRange(), the selection must be associated with a new range object, as required elsewhere in this specification.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-addrange">Selection API: 3 Selection interface</see>
    /// </remarks>
    [Description("@#addRange")]
    public extern void AddRange(Range range);

    /// <summary>
    /// This specification follows non-Gecko engines in restricting selections to at most one range, but the API was still originally designed for selections with arbitrary numbers of ranges. This explains oddities like the coexistence of removeRange() and removeAllRanges(), and a getRangeAt() method that takes an integer argument that must always be zero.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-removerange">Selection API: 3 Selection interface</see>
    /// </remarks>
    [Description("@#removeRange")]
    public extern void RemoveRange(Range range);

    /// <summary>
    /// This specification follows non-Gecko engines in restricting selections to at most one range, but the API was still originally designed for selections with arbitrary numbers of ranges. This explains oddities like the coexistence of removeRange() and removeAllRanges(), and a getRangeAt() method that takes an integer argument that must always be zero.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-removeallranges">Selection API: 3 Selection interface</see>
    /// </remarks>
    [Description("@#removeAllRanges")]
    public extern void RemoveAllRanges();

    /// <summary>
    /// Thus subsequent calls of this method returns the same range object if nothing has removed this&apos;s range in the meantime. In particular, getSelection().getRangeAt(0) === getSelection().getRangeAt(0) evaluates to true if the selection is not empty.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-empty">Selection API: 3 Selection interface</see>
    /// </remarks>
    [Description("@#empty")]
    public extern void Empty();

    /// <summary>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-getcomposedranges">Selection API: 3 Selection interface</see>
    /// </summary>
    [Description("@#getComposedRanges")]
    public extern StaticRange[] GetComposedRanges(GetComposedRangesOptions? options = default);

    /// <summary>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-collapse">Selection API: 3 Selection interface</see>
    /// </summary>
    [Description("@#collapse")]
    public extern void Collapse(Node? node, uint offset = 0);

    /// <summary>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-setposition">Selection API: 3 Selection interface</see>
    /// </summary>
    [Description("@#setPosition")]
    public extern void SetPosition(Node? node, uint offset = 0);

    /// <summary>
    /// <see href="https://w3c.github.io/selection-api/#dom-selection-collapsetostart">Selection API: 3 Selection interface</see>
    /// </summary>
