/// <summary>
/// The Touch Events specification provides a solution to this problem by specifying interfaces to allow web applications to directly handle touch events, and multiple touch points for capable devices.
/// </summary>
/// <remarks>
/// <see href="https://w3c.github.io/touch-events/#dom-touch">Touch Events - Level 2: 3 Touch Interface</see>
/// </remarks>
[ECMAScript]
[Description("@#Touch")]
public class Touch
{
    /// <summary>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-constructor">Touch Events - Level 2: 3 Touch Interface</see>
    /// </summary>
    public extern Touch(TouchInit touchInitDict);

    /// <summary>
    /// When a touch point becomes active, it must be assigned an identifier that is distinct from any other active touch point. While the touch point remains active, all events that refer to it must assign it the same identifier.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-identifier">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#identifier")]
    public extern int Identifier { get; }

    /// <summary>
    /// Note: Both ways of reflecting IDL attributes allow for simply getting and setting the property on the platform object to work. For example, given a Touch object aTouch, evaluating aTouch.target would return the EventTarget for the Touch object. If the user agent implements IDL attributes as accessor properties, then the property access invokes the getter which returns the EventTarget....
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-target">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#target")]
    public extern EventTarget Target { get; }

    /// <summary>
    /// The radius of the ellipse which most closely circumscribes the touching area (e.g. finger, stylus) along the axis indicated by rotationAngle, in CSS pixels (as defined by !CSS-VALUES) of the same scale as screenX; 0 if no value is known. The value must not be negative.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-screenx">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#screenX")]
    public extern double ScreenX { get; }

    /// <summary>
    /// The radius of the ellipse which most closely circumscribes the touching area (e.g. finger, stylus) along the axis perpendicular to that indicated by rotationAngle, in CSS pixels (as defined by !CSS-VALUES) of the same scale as screenY; 0 if no value is known. The value must not be negative.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-screeny">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#screenY")]
    public extern double ScreenY { get; }

    /// <summary>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-clientx">Touch Events - Level 2: 3 Touch Interface</see>
    /// </summary>
    [Description("@#clientX")]
    public extern double ClientX { get; }

    /// <summary>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-clienty">Touch Events - Level 2: 3 Touch Interface</see>
    /// </summary>
    [Description("@#clientY")]
    public extern double ClientY { get; }

    /// <summary>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-pagex">Touch Events - Level 2: 3 Touch Interface</see>
    /// </summary>
    [Description("@#pageX")]
    public extern double PageX { get; }

    /// <summary>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-pagey">Touch Events - Level 2: 3 Touch Interface</see>
    /// </summary>
    [Description("@#pageY")]
    public extern double PageY { get; }

    /// <summary>
    /// Added radiusX and radiusY attributes to Touch
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-radiusx">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#radiusX")]
    public extern float RadiusX { get; }

    /// <summary>
    /// Added radiusX and radiusY attributes to Touch
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-radiusy">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#radiusY")]
    public extern float RadiusY { get; }

    /// <summary>
    /// Added rotationAngle attribute to Touch
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-rotationangle">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#rotationAngle")]
    public extern float RotationAngle { get; }

    /// <summary>
    /// A relative value of pressure applied, in the range 0 to 1, where 0 is no pressure, and 1 is the highest level of pressure the touch device is capable of sensing; 0 if no value is known. In environments where force is known, the absolute pressure represented by the force attribute, and the sensitivity in levels of pressure, may vary.
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-force">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#force")]
    public extern float Force { get; }

    /// <summary>
    /// Reword altitudeAngle/azimuthAngle descriptions in line with PointerEvents, add illustrations
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-altitudeangle">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#altitudeAngle")]
    public extern float AltitudeAngle { get; }

    /// <summary>
    /// Reword altitudeAngle/azimuthAngle descriptions in line with PointerEvents, add illustrations
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-azimuthangle">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#azimuthAngle")]
    public extern float AzimuthAngle { get; }

    /// <summary>
    /// Add touchType, altitudeAngle, azimuthAngle (Safari iOS 10.3 extensions for stylus)
    /// </summary>
    /// <remarks>
    /// <see href="https://w3c.github.io/touch-events/#dom-touch-touchtype">Touch Events - Level 2: 3 Touch Interface</see>
    /// </remarks>
    [Description("@#touchType")]
    public extern TouchType TouchType { get; }
}

