    public extern PromiseResult CropTo(CropTarget? cropTarget);

    /// <summary>
    /// <see href="https://w3c.github.io/mediacapture-region/#dom-browsercapturemediastreamtrack-clone">Region Capture: 6.1 BrowserCaptureMediaStreamTrack</see>
    /// </summary>
    [Description("@#clone")]
    public new extern BrowserCaptureMediaStreamTrack Clone();
}

